           const currentSpecs = {'画面サイズ': '32 V型(インチ)', '画素数': '1366x768', 'パネル種類': 'VAパネル', 'HDR方式': 'None', '映像処理エンジン': 'None', 'バックライト': '直下型LEDバックライト', '量子ドット': 'None', '倍速機能': 'None', 'BS 8K': 'None', 'BS 4K/110度CS 4K': 'None', '録画機能': '外付けHDD', 'ドライブ内蔵': 'None', '自動録画機能': 'None', '2番組同時録画': 'None', '早見再生': '1.3 倍速', 'スマートスピーカー連携': 'None', '回転式スタンド': 'None', 'HDMI端子': '2端子ARC対応', 'リモコン(音声操作)': 'None', 'スピーカー数': 'None', '幅x高さx奥行': 'None', '重量': '4.3 kg'};



           // ====================================================================
